SET NAMES utf8mb4;
DROP DATABASE IF EXISTS splitwise_plus;

CREATE DATABASE splitwise_plus
  CHARACTER SET utf8mb4
  COLLATE utf8mb4_0900_ai_ci;

USE splitwise_plus;

-- >>> schema/02_tables.sql
-- =====================================================================
-- SplitWise+ | 02_tables.sql — 14 tables, keys and constraints
-- Order respects FK dependencies. See docs/DATABASE_SCHEMA.md.
-- Note: MySQL 8 forbids CASCADE/SET NULL FK actions on columns that are
-- used in CHECK constraints, so those FKs use RESTRICT.
-- =====================================================================
SET NAMES utf8mb4;
USE splitwise_plus;

-- 1. users ------------------------------------------------------------
CREATE TABLE users (
  user_id        INT UNSIGNED  NOT NULL AUTO_INCREMENT,
  username       VARCHAR(30)   NOT NULL,
  email          VARCHAR(100)  NOT NULL,
  password_hash  VARCHAR(255)  NOT NULL,
  full_name      VARCHAR(100)  NOT NULL,
  phone          VARCHAR(15)   NULL,
  avatar_path    VARCHAR(255)  NULL,
  role           ENUM('user','admin') NOT NULL DEFAULT 'user',
  is_active      TINYINT(1)    NOT NULL DEFAULT 1,
  notify_email   TINYINT(1)    NOT NULL DEFAULT 1,
  last_login_at  DATETIME      NULL,
  created_at     DATETIME      NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at     DATETIME      NULL ON UPDATE CURRENT_TIMESTAMP,
  CONSTRAINT pk_users PRIMARY KEY (user_id),
  CONSTRAINT uq_users_username UNIQUE (username),
  CONSTRAINT uq_users_email UNIQUE (email),
  CONSTRAINT chk_users_username_len CHECK (CHAR_LENGTH(username) >= 3),
  CONSTRAINT chk_users_email_format CHECK (email LIKE '%_@_%._%'),
  CONSTRAINT chk_users_is_active CHECK (is_active IN (0,1))
) ENGINE=InnoDB;

-- 2. expense_groups ("groups" is reserved in MySQL 8) -----------------
CREATE TABLE expense_groups (
  group_id     INT UNSIGNED NOT NULL AUTO_INCREMENT,
  name         VARCHAR(80)  NOT NULL,
  description  VARCHAR(255) NULL,
  group_type   ENUM('trip','home','family','friends','work','other') NOT NULL DEFAULT 'other',
  created_by   INT UNSIGNED NOT NULL,
  is_archived  TINYINT(1)   NOT NULL DEFAULT 0,
  created_at   DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at   DATETIME     NULL ON UPDATE CURRENT_TIMESTAMP,
  CONSTRAINT pk_expense_groups PRIMARY KEY (group_id),
  CONSTRAINT fk_expense_groups_created_by FOREIGN KEY (created_by)
    REFERENCES users (user_id) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT chk_expense_groups_name CHECK (CHAR_LENGTH(TRIM(name)) > 0)
) ENGINE=InnoDB;

-- 3. group_members (users M:N groups) ---------------------------------
CREATE TABLE group_members (
  membership_id INT UNSIGNED NOT NULL AUTO_INCREMENT,
  group_id      INT UNSIGNED NOT NULL,
  user_id       INT UNSIGNED NOT NULL,
  role          ENUM('admin','member') NOT NULL DEFAULT 'member',
  status        ENUM('active','left','removed') NOT NULL DEFAULT 'active',
  joined_at     DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
  left_at       DATETIME     NULL,
  added_by      INT UNSIGNED NULL,
  CONSTRAINT pk_group_members PRIMARY KEY (membership_id),
  CONSTRAINT uq_group_members_group_user UNIQUE (group_id, user_id),
  CONSTRAINT fk_group_members_group FOREIGN KEY (group_id)
    REFERENCES expense_groups (group_id) ON DELETE CASCADE,
  CONSTRAINT fk_group_members_user FOREIGN KEY (user_id)
    REFERENCES users (user_id) ON DELETE RESTRICT,
  CONSTRAINT fk_group_members_added_by FOREIGN KEY (added_by)
    REFERENCES users (user_id) ON DELETE SET NULL,
  CONSTRAINT chk_group_members_left CHECK (
    (status = 'active' AND left_at IS NULL) OR (status <> 'active' AND left_at IS NOT NULL))
) ENGINE=InnoDB;

-- 4. group_invitations ------------------------------------------------
CREATE TABLE group_invitations (
  invitation_id   INT UNSIGNED NOT NULL AUTO_INCREMENT,
  group_id        INT UNSIGNED NOT NULL,
  invited_user_id INT UNSIGNED NOT NULL,
  invited_by      INT UNSIGNED NOT NULL,
  status          ENUM('pending','accepted','declined','cancelled') NOT NULL DEFAULT 'pending',
  created_at      DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  responded_at    DATETIME NULL,
  -- 1 while pending, NULL otherwise: lets UNIQUE allow only one pending invite
  pending_flag    TINYINT GENERATED ALWAYS AS (IF(status = 'pending', 1, NULL)) STORED,
  CONSTRAINT pk_group_invitations PRIMARY KEY (invitation_id),
  CONSTRAINT uq_group_invitations_one_pending UNIQUE (group_id, invited_user_id, pending_flag),
  CONSTRAINT fk_group_invitations_group FOREIGN KEY (group_id)
    REFERENCES expense_groups (group_id) ON DELETE CASCADE,
  CONSTRAINT fk_group_invitations_invited FOREIGN KEY (invited_user_id)
    REFERENCES users (user_id) ON DELETE RESTRICT,
  CONSTRAINT fk_group_invitations_by FOREIGN KEY (invited_by)
    REFERENCES users (user_id) ON DELETE RESTRICT,
  CONSTRAINT chk_group_invitations_self CHECK (invited_user_id <> invited_by),
  CONSTRAINT chk_group_invitations_resp CHECK (
    (status = 'pending' AND responded_at IS NULL) OR (status <> 'pending' AND responded_at IS NOT NULL))
) ENGINE=InnoDB;

-- 5. categories (self-referencing hierarchy) --------------------------
CREATE TABLE categories (
  category_id        SMALLINT UNSIGNED NOT NULL AUTO_INCREMENT,
  name               VARCHAR(50) NOT NULL,
  parent_category_id SMALLINT UNSIGNED NULL,
  icon               VARCHAR(50) NOT NULL DEFAULT 'bi-tag',
  color              CHAR(7)     NOT NULL DEFAULT '#6c757d',
  is_active          TINYINT(1)  NOT NULL DEFAULT 1,
  CONSTRAINT pk_categories PRIMARY KEY (category_id),
  CONSTRAINT uq_categories_name UNIQUE (name),
  CONSTRAINT fk_categories_parent FOREIGN KEY (parent_category_id)
    REFERENCES categories (category_id) ON DELETE RESTRICT,
  CONSTRAINT chk_categories_color CHECK (color REGEXP '^#[0-9A-Fa-f]{6}$')
) ENGINE=InnoDB;

-- 6. expenses ---------------------------------------------------------
CREATE TABLE expenses (
  expense_id    INT UNSIGNED  NOT NULL AUTO_INCREMENT,
  group_id      INT UNSIGNED  NULL,              -- NULL = personal expense
  paid_by       INT UNSIGNED  NOT NULL,
  created_by    INT UNSIGNED  NOT NULL,
  category_id   SMALLINT UNSIGNED NOT NULL,
  description   VARCHAR(120)  NOT NULL,
  total_amount  DECIMAL(12,2) NOT NULL,
  split_method  ENUM('equal','percentage','exact','shares','adjustment') NOT NULL DEFAULT 'equal',
  expense_date  DATE          NOT NULL,
  notes         VARCHAR(500)  NULL,
  is_deleted    TINYINT(1)    NOT NULL DEFAULT 0,
  deleted_at    DATETIME      NULL,
  deleted_by    INT UNSIGNED  NULL,
  version       INT UNSIGNED  NOT NULL DEFAULT 1,
  created_at    DATETIME      NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at    DATETIME      NULL ON UPDATE CURRENT_TIMESTAMP,
  CONSTRAINT pk_expenses PRIMARY KEY (expense_id),
  CONSTRAINT fk_expenses_group FOREIGN KEY (group_id)
    REFERENCES expense_groups (group_id) ON DELETE RESTRICT,
  CONSTRAINT fk_expenses_paid_by FOREIGN KEY (paid_by)
    REFERENCES users (user_id) ON DELETE RESTRICT,
  CONSTRAINT fk_expenses_created_by FOREIGN KEY (created_by)
    REFERENCES users (user_id) ON DELETE RESTRICT,
  CONSTRAINT fk_expenses_category FOREIGN KEY (category_id)
    REFERENCES categories (category_id) ON DELETE RESTRICT,
  CONSTRAINT fk_expenses_deleted_by FOREIGN KEY (deleted_by)
    REFERENCES users (user_id) ON DELETE SET NULL,
  CONSTRAINT chk_expenses_amount CHECK (total_amount > 0),
  CONSTRAINT chk_expenses_description CHECK (CHAR_LENGTH(TRIM(description)) > 0),
  CONSTRAINT chk_expenses_soft_delete CHECK (
    (is_deleted = 0 AND deleted_at IS NULL) OR (is_deleted = 1 AND deleted_at IS NOT NULL))
) ENGINE=InnoDB;

-- 7. expense_splits (expenses M:N users) ------------------------------
CREATE TABLE expense_splits (
  split_id          INT UNSIGNED  NOT NULL AUTO_INCREMENT,
  expense_id        INT UNSIGNED  NOT NULL,
  user_id           INT UNSIGNED  NOT NULL,
  share_amount      DECIMAL(12,2) NOT NULL,     -- binding obligation
  share_percentage  DECIMAL(5,2)  NULL,         -- input for 'percentage'
  share_units       DECIMAL(6,2)  NULL,         -- input for 'shares'
  share_adjustment  DECIMAL(12,2) NULL,         -- input for 'adjustment'
  CONSTRAINT pk_expense_splits PRIMARY KEY (split_id),
  CONSTRAINT uq_expense_splits_expense_user UNIQUE (expense_id, user_id),
  CONSTRAINT fk_expense_splits_expense FOREIGN KEY (expense_id)
    REFERENCES expenses (expense_id) ON DELETE CASCADE,
  CONSTRAINT fk_expense_splits_user FOREIGN KEY (user_id)
    REFERENCES users (user_id) ON DELETE RESTRICT,
  CONSTRAINT chk_expense_splits_amount CHECK (share_amount >= 0),
  CONSTRAINT chk_expense_splits_pct CHECK (share_percentage IS NULL OR share_percentage BETWEEN 0 AND 100),
  CONSTRAINT chk_expense_splits_units CHECK (share_units IS NULL OR share_units > 0)
) ENGINE=InnoDB;

-- 8. settlements ------------------------------------------------------
CREATE TABLE settlements (
  settlement_id   INT UNSIGNED  NOT NULL AUTO_INCREMENT,
  group_id        INT UNSIGNED  NOT NULL,
  payer_id        INT UNSIGNED  NOT NULL,
  payee_id        INT UNSIGNED  NOT NULL,
  amount          DECIMAL(12,2) NOT NULL,
  settlement_date DATE          NOT NULL,
  method          ENUM('cash','upi','bank_transfer','other') NOT NULL DEFAULT 'cash',
  note            VARCHAR(255)  NULL,
  status          ENUM('pending','confirmed','rejected','cancelled') NOT NULL DEFAULT 'pending',
  created_by      INT UNSIGNED  NOT NULL,
  responded_at    DATETIME      NULL,
  request_token   CHAR(36)      NOT NULL,
  created_at      DATETIME      NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at      DATETIME      NULL ON UPDATE CURRENT_TIMESTAMP,
  CONSTRAINT pk_settlements PRIMARY KEY (settlement_id),
  CONSTRAINT uq_settlements_token UNIQUE (request_token),
  CONSTRAINT fk_settlements_group FOREIGN KEY (group_id)
    REFERENCES expense_groups (group_id) ON DELETE RESTRICT,
  CONSTRAINT fk_settlements_payer FOREIGN KEY (payer_id)
    REFERENCES users (user_id) ON DELETE RESTRICT,
  CONSTRAINT fk_settlements_payee FOREIGN KEY (payee_id)
    REFERENCES users (user_id) ON DELETE RESTRICT,
  CONSTRAINT fk_settlements_created_by FOREIGN KEY (created_by)
    REFERENCES users (user_id) ON DELETE RESTRICT,
  CONSTRAINT chk_settlements_amount CHECK (amount > 0),
  CONSTRAINT chk_settlements_parties CHECK (payer_id <> payee_id)
) ENGINE=InnoDB;

-- 9. budgets ----------------------------------------------------------
CREATE TABLE budgets (
  budget_id       INT UNSIGNED  NOT NULL AUTO_INCREMENT,
  user_id         INT UNSIGNED  NULL,
  group_id        INT UNSIGNED  NULL,
  category_id     SMALLINT UNSIGNED NULL,       -- NULL = all categories
  name            VARCHAR(80)   NOT NULL,
  limit_amount    DECIMAL(12,2) NOT NULL,
  period_type     ENUM('weekly','monthly','yearly','custom') NOT NULL,
  start_date      DATE          NOT NULL,
  end_date        DATE          NOT NULL,
  alert_threshold TINYINT UNSIGNED NOT NULL DEFAULT 80,
  is_active       TINYINT(1)    NOT NULL DEFAULT 1,
  created_by      INT UNSIGNED  NOT NULL,
  created_at      DATETIME      NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at      DATETIME      NULL ON UPDATE CURRENT_TIMESTAMP,
  CONSTRAINT pk_budgets PRIMARY KEY (budget_id),
  CONSTRAINT fk_budgets_user FOREIGN KEY (user_id)
    REFERENCES users (user_id) ON DELETE RESTRICT,
  CONSTRAINT fk_budgets_group FOREIGN KEY (group_id)
    REFERENCES expense_groups (group_id) ON DELETE RESTRICT,
  CONSTRAINT fk_budgets_category FOREIGN KEY (category_id)
    REFERENCES categories (category_id) ON DELETE RESTRICT,
  CONSTRAINT fk_budgets_created_by FOREIGN KEY (created_by)
    REFERENCES users (user_id) ON DELETE RESTRICT,
  CONSTRAINT chk_budgets_limit CHECK (limit_amount > 0),
  CONSTRAINT chk_budgets_period CHECK (end_date >= start_date),
  CONSTRAINT chk_budgets_threshold CHECK (alert_threshold BETWEEN 1 AND 100),
  CONSTRAINT chk_budgets_owner CHECK ((user_id IS NULL) <> (group_id IS NULL))
) ENGINE=InnoDB;

-- 10. notifications ---------------------------------------------------
CREATE TABLE notifications (
  notification_id INT UNSIGNED NOT NULL AUTO_INCREMENT,
  user_id         INT UNSIGNED NOT NULL,
  type            ENUM('group_invite','expense_added','expense_updated','expense_deleted',
                       'settlement_request','settlement_confirmed','settlement_rejected',
                       'budget_warning','member_removed') NOT NULL,
  title           VARCHAR(120) NOT NULL,
  message         VARCHAR(255) NOT NULL,
  entity_type     ENUM('group','expense','settlement','budget','invitation') NULL,
  entity_id       INT UNSIGNED NULL,     -- polymorphic pointer, no FK (documented)
  is_read         TINYINT(1)   NOT NULL DEFAULT 0,
  read_at         DATETIME     NULL,
  created_at      DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT pk_notifications PRIMARY KEY (notification_id),
  CONSTRAINT fk_notifications_user FOREIGN KEY (user_id)
    REFERENCES users (user_id) ON DELETE CASCADE,
  CONSTRAINT chk_notifications_entity CHECK ((entity_type IS NULL) = (entity_id IS NULL))
) ENGINE=InnoDB;

-- 11. receipts --------------------------------------------------------
CREATE TABLE receipts (
  receipt_id    INT UNSIGNED NOT NULL AUTO_INCREMENT,
  expense_id    INT UNSIGNED NOT NULL,
  file_path     VARCHAR(255) NOT NULL,
  original_name VARCHAR(255) NOT NULL,
  mime_type     VARCHAR(50)  NOT NULL,
  file_size     INT UNSIGNED NOT NULL,
  content       LONGBLOB     NULL,           -- file bytes (Phase 5.5: stored in MySQL, not on disk)
  uploaded_by   INT UNSIGNED NOT NULL,
  uploaded_at   DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT pk_receipts PRIMARY KEY (receipt_id),
  CONSTRAINT uq_receipts_path UNIQUE (file_path),
  CONSTRAINT fk_receipts_expense FOREIGN KEY (expense_id)
    REFERENCES expenses (expense_id) ON DELETE CASCADE,
  CONSTRAINT fk_receipts_uploaded_by FOREIGN KEY (uploaded_by)
    REFERENCES users (user_id) ON DELETE RESTRICT,
  CONSTRAINT chk_receipts_mime CHECK (mime_type IN ('image/jpeg','image/png','application/pdf')),
  CONSTRAINT chk_receipts_size CHECK (file_size BETWEEN 1 AND 5242880)
) ENGINE=InnoDB;

-- 12. tags ------------------------------------------------------------
CREATE TABLE tags (
  tag_id INT UNSIGNED NOT NULL AUTO_INCREMENT,
  name   VARCHAR(30)  NOT NULL,
  CONSTRAINT pk_tags PRIMARY KEY (tag_id),
  CONSTRAINT uq_tags_name UNIQUE (name),
  CONSTRAINT chk_tags_lower CHECK (BINARY name = BINARY LOWER(name))
) ENGINE=InnoDB;

-- 13. expense_tags (expenses M:N tags) --------------------------------
CREATE TABLE expense_tags (
  expense_id INT UNSIGNED NOT NULL,
  tag_id     INT UNSIGNED NOT NULL,
  CONSTRAINT pk_expense_tags PRIMARY KEY (expense_id, tag_id),
  CONSTRAINT fk_expense_tags_expense FOREIGN KEY (expense_id)
    REFERENCES expenses (expense_id) ON DELETE CASCADE,
  CONSTRAINT fk_expense_tags_tag FOREIGN KEY (tag_id)
    REFERENCES tags (tag_id) ON DELETE CASCADE
) ENGINE=InnoDB;

-- 14. audit_logs (written by triggers only; no FK by design) ----------
CREATE TABLE audit_logs (
  log_id      BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  table_name  VARCHAR(64)  NOT NULL,
  record_id   INT UNSIGNED NOT NULL,
  action      ENUM('INSERT','UPDATE','DELETE','SOFT_DELETE','RESTORE') NOT NULL,
  old_data    JSON         NULL,
  new_data    JSON         NULL,
  changed_by  INT UNSIGNED NULL,
  changed_at  DATETIME(3)  NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  CONSTRAINT pk_audit_logs PRIMARY KEY (log_id)
) ENGINE=InnoDB;

-- >>> schema/03_indexes.sql
-- =====================================================================
-- SplitWise+ | 03_indexes.sql — secondary indexes (reasons in DATABASE_SCHEMA.md §8)
-- UNIQUE indexes are declared with the tables. InnoDB drops its own
-- implicit FK index once one of these can serve the FK instead.
-- =====================================================================
SET NAMES utf8mb4;
USE splitwise_plus;

-- "my groups" page
CREATE INDEX idx_group_members_user_status ON group_members (user_id, status);
-- group history sorted by date, balance sums over active expenses
CREATE INDEX idx_expenses_group_deleted_date ON expenses (group_id, is_deleted, expense_date);
-- paid() aggregation per user
CREATE INDEX idx_expenses_paid_by ON expenses (paid_by);
-- category reports and budget windows
CREATE INDEX idx_expenses_category_date ON expenses (category_id, expense_date);
-- owed() aggregation, "my expenses"
CREATE INDEX idx_expense_splits_user ON expense_splits (user_id);
-- balance sums and settlement history per group
CREATE INDEX idx_settlements_group_status ON settlements (group_id, status);
CREATE INDEX idx_settlements_payer ON settlements (payer_id);
CREATE INDEX idx_settlements_payee ON settlements (payee_id);
-- unread badge, newest first
CREATE INDEX idx_notifications_user_read_date ON notifications (user_id, is_read, created_at);
-- record history in admin activity view
CREATE INDEX idx_audit_logs_record ON audit_logs (table_name, record_id);
CREATE INDEX idx_audit_logs_changed_at ON audit_logs (changed_at);
-- M:N reverse lookup: expenses by tag
CREATE INDEX idx_expense_tags_tag ON expense_tags (tag_id);
-- budget lists
CREATE INDEX idx_budgets_user ON budgets (user_id);
CREATE INDEX idx_budgets_group ON budgets (group_id);

-- >>> schema/04_infrastructure.sql
SET NAMES utf8mb4;
-- =====================================================================
-- SplitWise+ | 04_infrastructure.sql — shared state for multi-instance hosting
-- (Phase 5.5). On Vercel each request may reach a different container and
-- the container disk is thrown away, so state that used to live in files
-- lives in MySQL instead. Neither table holds business data.
-- =====================================================================
USE splitwise_plus;

-- PHP sessions (App\Core\DbSessionHandler). Unix timestamps avoid time-zone mix-ups.
CREATE TABLE app_sessions (
  session_id    VARCHAR(128)  NOT NULL,
  payload       MEDIUMBLOB    NOT NULL,
  last_activity INT UNSIGNED  NOT NULL,
  CONSTRAINT pk_app_sessions PRIMARY KEY (session_id),
  INDEX idx_app_sessions_activity (last_activity)
) ENGINE=InnoDB;

-- Small expiring counters/values: login-throttle counters, the mock-mail cursor.
CREATE TABLE app_kv (
  kv_key     VARCHAR(100) NOT NULL,
  kv_value   VARCHAR(255) NOT NULL,
  expires_at INT UNSIGNED NULL,          -- NULL = never expires
  CONSTRAINT pk_app_kv PRIMARY KEY (kv_key),
  INDEX idx_app_kv_expires (expires_at)
) ENGINE=InnoDB;

-- >>> functions/functions.sql
-- =====================================================================
-- SplitWise+ | functions.sql — stored functions
-- READS SQL DATA is required when binary logging is on (MySQL 8 default).
-- =====================================================================
SET NAMES utf8mb4;
USE splitwise_plus;

DROP FUNCTION IF EXISTS fn_member_net_balance;
DROP FUNCTION IF EXISTS fn_expense_split_gap;
DROP FUNCTION IF EXISTS fn_budget_spent;

DELIMITER $$

-- net = paid - owed + sent - received  (positive = gets money back)
CREATE FUNCTION fn_member_net_balance(p_group_id INT UNSIGNED, p_user_id INT UNSIGNED)
RETURNS DECIMAL(12,2)
READS SQL DATA
BEGIN
  DECLARE v_paid, v_owed, v_sent, v_received DECIMAL(12,2) DEFAULT 0;

  SELECT COALESCE(SUM(total_amount), 0) INTO v_paid
    FROM expenses
   WHERE group_id = p_group_id AND paid_by = p_user_id AND is_deleted = 0;

  SELECT COALESCE(SUM(s.share_amount), 0) INTO v_owed
    FROM expense_splits s
    JOIN expenses e ON e.expense_id = s.expense_id
   WHERE e.group_id = p_group_id AND s.user_id = p_user_id AND e.is_deleted = 0;

  SELECT COALESCE(SUM(amount), 0) INTO v_sent
    FROM settlements
   WHERE group_id = p_group_id AND payer_id = p_user_id AND status = 'confirmed';

  SELECT COALESCE(SUM(amount), 0) INTO v_received
    FROM settlements
   WHERE group_id = p_group_id AND payee_id = p_user_id AND status = 'confirmed';

  RETURN v_paid - v_owed + v_sent - v_received;
END$$

-- total - sum(shares). Must be 0.00 for every valid expense. NULL if expense missing.
CREATE FUNCTION fn_expense_split_gap(p_expense_id INT UNSIGNED)
RETURNS DECIMAL(12,2)
READS SQL DATA
BEGIN
  DECLARE v_gap DECIMAL(12,2);
  SELECT e.total_amount - COALESCE((SELECT SUM(s.share_amount)
                                      FROM expense_splits s
                                     WHERE s.expense_id = e.expense_id), 0)
    INTO v_gap
    FROM expenses e
   WHERE e.expense_id = p_expense_id;
  RETURN v_gap;
END$$

-- Personal budget: the owner's SHARE of expenses. Group budget: group expense totals.
-- A category budget also counts its sub-categories (e.g. Food & Dining -> Groceries).
CREATE FUNCTION fn_budget_spent(p_budget_id INT UNSIGNED)
RETURNS DECIMAL(12,2)
READS SQL DATA
BEGIN
  DECLARE v_user, v_group INT UNSIGNED;
  DECLARE v_cat SMALLINT UNSIGNED;
  DECLARE v_start, v_end DATE;
  DECLARE v_spent DECIMAL(12,2) DEFAULT 0;

  SELECT user_id, group_id, category_id, start_date, end_date
    INTO v_user, v_group, v_cat, v_start, v_end
    FROM budgets WHERE budget_id = p_budget_id;

  IF v_user IS NOT NULL THEN
    SELECT COALESCE(SUM(s.share_amount), 0) INTO v_spent
      FROM expense_splits s
      JOIN expenses   e ON e.expense_id = s.expense_id
      JOIN categories c ON c.category_id = e.category_id
     WHERE s.user_id = v_user
       AND e.is_deleted = 0
       AND e.expense_date BETWEEN v_start AND v_end
       AND (v_cat IS NULL OR v_cat IN (c.category_id, c.parent_category_id));
  ELSEIF v_group IS NOT NULL THEN
    SELECT COALESCE(SUM(e.total_amount), 0) INTO v_spent
      FROM expenses e
      JOIN categories c ON c.category_id = e.category_id
     WHERE e.group_id = v_group
       AND e.is_deleted = 0
       AND e.expense_date BETWEEN v_start AND v_end
       AND (v_cat IS NULL OR v_cat IN (c.category_id, c.parent_category_id));
  END IF;

  RETURN v_spent;
END$$

DELIMITER ;

-- >>> views/views.sql
-- =====================================================================
-- SplitWise+ | views.sql — 11 views (Experiment 9)
-- Updatable: v_active_expenses, v_active_group_members (single table, no
-- aggregates/DISTINCT/GROUP BY/UNION/subquery in select list).
-- All others are read-only by MySQL's view rules.
-- =====================================================================
SET NAMES utf8mb4;
USE splitwise_plus;

-- 1. Simple single-table, UPDATABLE, WITH CHECK OPTION -----------------
--    An UPDATE through this view that sets is_deleted = 1 is rejected
--    because the row would leave the view.
CREATE OR REPLACE VIEW v_active_expenses AS
SELECT expense_id, group_id, paid_by, created_by, category_id, description,
       total_amount, split_method, expense_date, notes, is_deleted, version,
       created_at, updated_at
  FROM expenses
 WHERE is_deleted = 0
WITH CASCADED CHECK OPTION;

-- 2. Simple single-table, UPDATABLE -------------------------------------
CREATE OR REPLACE VIEW v_active_group_members AS
SELECT membership_id, group_id, user_id, role, status, joined_at
  FROM group_members
 WHERE status = 'active';

-- 3. Join view: expense with payer, category (+parent), group ----------
CREATE OR REPLACE VIEW v_expense_details AS
SELECT e.expense_id,
       e.expense_date,
       e.description,
       e.total_amount,
       e.split_method,
       e.group_id,
       COALESCE(g.name, 'Personal') AS group_name,
       e.paid_by,
       payer.full_name              AS payer_name,
       c.name                       AS category_name,
       COALESCE(pc.name, c.name)    AS parent_category_name,
       e.notes,
       e.is_deleted
  FROM expenses e
  JOIN users payer          ON payer.user_id = e.paid_by
  JOIN categories c         ON c.category_id = e.category_id
  LEFT JOIN categories pc   ON pc.category_id = c.parent_category_id
  LEFT JOIN expense_groups g ON g.group_id = e.group_id;

-- 4. Join view: users joined twice (payer / payee aliases) --------------
CREATE OR REPLACE VIEW v_settlement_details AS
SELECT s.settlement_id,
       s.group_id,
       g.name        AS group_name,
       s.payer_id,
       p.full_name   AS payer_name,
       s.payee_id,
       r.full_name   AS payee_name,
       s.amount,
       s.settlement_date,
       s.method,
       s.status,
       s.note
  FROM settlements s
  JOIN users p           ON p.user_id = s.payer_id
  JOIN users r           ON r.user_id = s.payee_id
  JOIN expense_groups g  ON g.group_id = s.group_id;

-- 5. Balance per member per group (derived tables + aggregates) ---------
--    net = paid - owed + sent - received
CREATE OR REPLACE VIEW v_group_member_balances AS
SELECT gm.group_id,
       g.name                       AS group_name,
       gm.user_id,
       u.full_name,
       gm.status                    AS member_status,
       COALESCE(pd.paid, 0)         AS total_paid,
       COALESCE(ow.owed, 0)         AS total_owed,
       COALESCE(st.sent, 0)         AS settled_paid,
       COALESCE(rc.received, 0)     AS settled_received,
       COALESCE(pd.paid, 0) - COALESCE(ow.owed, 0)
         + COALESCE(st.sent, 0) - COALESCE(rc.received, 0) AS net_balance
  FROM group_members gm
  JOIN users u           ON u.user_id = gm.user_id
  JOIN expense_groups g  ON g.group_id = gm.group_id
  LEFT JOIN (SELECT group_id, paid_by AS user_id, SUM(total_amount) AS paid
               FROM expenses
              WHERE is_deleted = 0 AND group_id IS NOT NULL
              GROUP BY group_id, paid_by) pd
         ON pd.group_id = gm.group_id AND pd.user_id = gm.user_id
  LEFT JOIN (SELECT e.group_id, s.user_id, SUM(s.share_amount) AS owed
               FROM expense_splits s
               JOIN expenses e ON e.expense_id = s.expense_id
              WHERE e.is_deleted = 0 AND e.group_id IS NOT NULL
              GROUP BY e.group_id, s.user_id) ow
         ON ow.group_id = gm.group_id AND ow.user_id = gm.user_id
  LEFT JOIN (SELECT group_id, payer_id AS user_id, SUM(amount) AS sent
               FROM settlements WHERE status = 'confirmed'
              GROUP BY group_id, payer_id) st
         ON st.group_id = gm.group_id AND st.user_id = gm.user_id
  LEFT JOIN (SELECT group_id, payee_id AS user_id, SUM(amount) AS received
               FROM settlements WHERE status = 'confirmed'
              GROUP BY group_id, payee_id) rc
         ON rc.group_id = gm.group_id AND rc.user_id = gm.user_id;

-- 6. View based on another view: overall balance per user --------------
CREATE OR REPLACE VIEW v_user_overall_balance AS
SELECT user_id,
       full_name,
       SUM(total_paid)                                        AS total_paid,
       SUM(total_owed)                                        AS total_owed,
       SUM(net_balance)                                       AS net_balance,
       SUM(CASE WHEN net_balance > 0 THEN net_balance ELSE 0 END)  AS receivable,
       SUM(CASE WHEN net_balance < 0 THEN -net_balance ELSE 0 END) AS payable
  FROM v_group_member_balances
 GROUP BY user_id, full_name;

-- 7. Pairwise debts: "original owed / settled / remaining" -------------
--    Signed contributions are normalised to the pair (user_a < user_b).
--    outstanding > 0 means user_a owes user_b; < 0 means user_b owes user_a.
CREATE OR REPLACE VIEW v_pairwise_debts AS
SELECT t.group_id,
       t.user_a,
       t.user_b,
       SUM(t.gross_a_to_b)   AS gross_a_owes_b,
       SUM(t.gross_b_to_a)   AS gross_b_owes_a,
       SUM(t.settled_a_to_b) AS settled_a_paid_b,
       SUM(t.settled_b_to_a) AS settled_b_paid_a,
       SUM(t.gross_a_to_b) - SUM(t.gross_b_to_a)
         - SUM(t.settled_a_to_b) + SUM(t.settled_b_to_a) AS outstanding
  FROM (
        -- debts from expense splits: participant owes payer
        SELECT e.group_id,
               LEAST(s.user_id, e.paid_by)    AS user_a,
               GREATEST(s.user_id, e.paid_by) AS user_b,
               IF(s.user_id < e.paid_by, s.share_amount, 0) AS gross_a_to_b,
               IF(s.user_id > e.paid_by, s.share_amount, 0) AS gross_b_to_a,
               0 AS settled_a_to_b,
               0 AS settled_b_to_a
          FROM expense_splits s
          JOIN expenses e ON e.expense_id = s.expense_id
         WHERE e.is_deleted = 0 AND e.group_id IS NOT NULL AND s.user_id <> e.paid_by
        UNION ALL
        -- confirmed settlements reduce the payer's debt to the payee
        SELECT group_id,
               LEAST(payer_id, payee_id),
               GREATEST(payer_id, payee_id),
               0, 0,
               IF(payer_id < payee_id, amount, 0),
               IF(payer_id > payee_id, amount, 0)
          FROM settlements
         WHERE status = 'confirmed'
       ) t
 GROUP BY t.group_id, t.user_a, t.user_b;

-- 8. Aggregate view: group expense summary -----------------------------
CREATE OR REPLACE VIEW v_group_expense_summary AS
SELECT g.group_id,
       g.name                          AS group_name,
       COUNT(e.expense_id)             AS expense_count,
       COALESCE(SUM(e.total_amount),0) AS total_spent,
       ROUND(AVG(e.total_amount), 2)   AS avg_expense,
       MIN(e.total_amount)             AS min_expense,
       MAX(e.total_amount)             AS max_expense,
       MAX(e.expense_date)             AS last_expense_date
  FROM expense_groups g
  LEFT JOIN expenses e ON e.group_id = g.group_id AND e.is_deleted = 0
 GROUP BY g.group_id, g.name;

-- 9. Aggregate view: each user's share per month (personal + group) ----
CREATE OR REPLACE VIEW v_monthly_user_spending AS
SELECT s.user_id,
       u.full_name,
       DATE_FORMAT(e.expense_date, '%Y-%m') AS spend_month,
       COUNT(*)                             AS expense_count,
       SUM(s.share_amount)                  AS my_share
  FROM expense_splits s
  JOIN expenses e ON e.expense_id = s.expense_id
  JOIN users u    ON u.user_id = s.user_id
 WHERE e.is_deleted = 0
 GROUP BY s.user_id, u.full_name, DATE_FORMAT(e.expense_date, '%Y-%m');

-- 10. Subquery-based view: budget utilisation --------------------------
CREATE OR REPLACE VIEW v_budget_utilization AS
SELECT x.*,
       x.limit_amount - x.spent                    AS remaining,
       ROUND(x.spent * 100 / x.limit_amount, 2)    AS utilization_pct,
       CASE WHEN x.spent > x.limit_amount THEN 'over_budget'
            WHEN x.spent * 100 >= x.limit_amount * x.alert_threshold THEN 'warning'
            ELSE 'ok' END                          AS budget_status
  FROM (
        SELECT b.budget_id, b.name, b.user_id, b.group_id, b.category_id,
               b.limit_amount, b.period_type, b.start_date, b.end_date, b.alert_threshold,
               CASE
                 WHEN b.user_id IS NOT NULL THEN
                   (SELECT COALESCE(SUM(s.share_amount), 0)
                      FROM expense_splits s
                      JOIN expenses e   ON e.expense_id = s.expense_id
                      JOIN categories c ON c.category_id = e.category_id
                     WHERE s.user_id = b.user_id AND e.is_deleted = 0
                       AND e.expense_date BETWEEN b.start_date AND b.end_date
                       AND (b.category_id IS NULL
                            OR b.category_id IN (c.category_id, c.parent_category_id)))
                 ELSE
                   (SELECT COALESCE(SUM(e.total_amount), 0)
                      FROM expenses e
                      JOIN categories c ON c.category_id = e.category_id
                     WHERE e.group_id = b.group_id AND e.is_deleted = 0
                       AND e.expense_date BETWEEN b.start_date AND b.end_date
                       AND (b.category_id IS NULL
                            OR b.category_id IN (c.category_id, c.parent_category_id)))
               END AS spent
          FROM budgets b
         WHERE b.is_active = 1
       ) x;

-- 11. Correlated-subquery view: expenses above their group's average ---
CREATE OR REPLACE VIEW v_expenses_above_group_avg AS
SELECT e.expense_id, e.group_id, e.description, e.total_amount,
       (SELECT ROUND(AVG(e2.total_amount), 2)
          FROM expenses e2
         WHERE e2.group_id = e.group_id AND e2.is_deleted = 0) AS group_avg
  FROM expenses e
 WHERE e.group_id IS NOT NULL
   AND e.is_deleted = 0
   AND e.total_amount > (SELECT AVG(e3.total_amount)
                           FROM expenses e3
                          WHERE e3.group_id = e.group_id AND e3.is_deleted = 0);

-- >>> triggers/triggers.sql
-- =====================================================================
-- SplitWise+ | triggers.sql — Experiment 8
-- All six timing/event combinations, each with a business purpose.
-- MySQL triggers are row-level only (FOR EACH ROW); no COMMIT/ROLLBACK
-- inside; a trigger never modifies the table that fired it.
-- @app_user_id is set by the PHP app on each connection (who acted).
-- Caveat: FK cascades (e.g. ON DELETE CASCADE) do NOT fire triggers.
-- =====================================================================
SET NAMES utf8mb4;
USE splitwise_plus;

DROP TRIGGER IF EXISTS trg_expenses_before_insert;
DROP TRIGGER IF EXISTS trg_expenses_after_insert;
DROP TRIGGER IF EXISTS trg_expenses_after_update;
DROP TRIGGER IF EXISTS trg_expenses_after_delete;
DROP TRIGGER IF EXISTS trg_expense_splits_before_insert;
DROP TRIGGER IF EXISTS trg_expense_splits_after_insert;
DROP TRIGGER IF EXISTS trg_expense_splits_after_delete;
DROP TRIGGER IF EXISTS trg_settlements_after_insert;
DROP TRIGGER IF EXISTS trg_settlements_before_update;
DROP TRIGGER IF EXISTS trg_settlements_after_update;
DROP TRIGGER IF EXISTS trg_settlements_before_delete;

DELIMITER $$

-- BEFORE INSERT: validate a new expense ---------------------------------
CREATE TRIGGER trg_expenses_before_insert
BEFORE INSERT ON expenses
FOR EACH ROW
BEGIN
  SET NEW.description = TRIM(NEW.description);

  IF NEW.expense_date > CURDATE() THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Expense date cannot be in the future';
  END IF;

  IF NEW.group_id IS NOT NULL THEN
    IF (SELECT is_archived FROM expense_groups WHERE group_id = NEW.group_id) = 1 THEN
      SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Cannot add expenses to an archived group';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM group_members
                    WHERE group_id = NEW.group_id AND user_id = NEW.paid_by
                      AND status = 'active') THEN
      SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Payer must be an active member of the group';
    END IF;
  END IF;
END$$

-- AFTER INSERT: audit new expense ---------------------------------------
CREATE TRIGGER trg_expenses_after_insert
AFTER INSERT ON expenses
FOR EACH ROW
BEGIN
  INSERT INTO audit_logs (table_name, record_id, action, new_data, changed_by)
  VALUES ('expenses', NEW.expense_id, 'INSERT',
          JSON_OBJECT('group_id', NEW.group_id, 'paid_by', NEW.paid_by,
                      'description', NEW.description, 'total_amount', NEW.total_amount,
                      'split_method', NEW.split_method, 'expense_date', NEW.expense_date),
          @app_user_id);
END$$

-- AFTER UPDATE: audit OLD -> NEW, classify soft delete / restore, notify -
CREATE TRIGGER trg_expenses_after_update
AFTER UPDATE ON expenses
FOR EACH ROW
BEGIN
  DECLARE v_action VARCHAR(12);
  SET v_action = CASE
                   WHEN OLD.is_deleted = 0 AND NEW.is_deleted = 1 THEN 'SOFT_DELETE'
                   WHEN OLD.is_deleted = 1 AND NEW.is_deleted = 0 THEN 'RESTORE'
                   ELSE 'UPDATE' END;

  INSERT INTO audit_logs (table_name, record_id, action, old_data, new_data, changed_by)
  VALUES ('expenses', NEW.expense_id, v_action,
          JSON_OBJECT('description', OLD.description, 'total_amount', OLD.total_amount,
                      'paid_by', OLD.paid_by, 'category_id', OLD.category_id,
                      'split_method', OLD.split_method, 'expense_date', OLD.expense_date,
                      'is_deleted', OLD.is_deleted, 'version', OLD.version),
          JSON_OBJECT('description', NEW.description, 'total_amount', NEW.total_amount,
                      'paid_by', NEW.paid_by, 'category_id', NEW.category_id,
                      'split_method', NEW.split_method, 'expense_date', NEW.expense_date,
                      'is_deleted', NEW.is_deleted, 'version', NEW.version),
          @app_user_id);

  -- tell the other participants (not the person who made the change)
  IF NEW.group_id IS NOT NULL THEN
    INSERT INTO notifications (user_id, type, title, message, entity_type, entity_id)
    SELECT s.user_id,
           IF(v_action = 'SOFT_DELETE', 'expense_deleted', 'expense_updated'),
           IF(v_action = 'SOFT_DELETE', 'Expense deleted', 'Expense updated'),
           CONCAT('"', NEW.description, '" (₹', NEW.total_amount, ') was ',
                  LOWER(REPLACE(v_action, '_', ' ')), 'd'),
           'expense', NEW.expense_id
      FROM expense_splits s
     WHERE s.expense_id = NEW.expense_id
       AND s.user_id <> COALESCE(@app_user_id, 0);
  END IF;
END$$

-- AFTER DELETE: hard delete (admin cleanup only) is still audited -------
CREATE TRIGGER trg_expenses_after_delete
AFTER DELETE ON expenses
FOR EACH ROW
BEGIN
  INSERT INTO audit_logs (table_name, record_id, action, old_data, changed_by)
  VALUES ('expenses', OLD.expense_id, 'DELETE',
          JSON_OBJECT('group_id', OLD.group_id, 'paid_by', OLD.paid_by,
                      'description', OLD.description, 'total_amount', OLD.total_amount,
                      'expense_date', OLD.expense_date, 'is_deleted', OLD.is_deleted),
          @app_user_id);
END$$

-- BEFORE INSERT: participant must be allowed in this expense ------------
CREATE TRIGGER trg_expense_splits_before_insert
BEFORE INSERT ON expense_splits
FOR EACH ROW
BEGIN
  DECLARE v_group INT UNSIGNED;
  DECLARE v_payer INT UNSIGNED;
  DECLARE v_total DECIMAL(12,2);

  SELECT group_id, paid_by, total_amount INTO v_group, v_payer, v_total
    FROM expenses WHERE expense_id = NEW.expense_id;

  IF v_group IS NULL AND NEW.user_id <> v_payer THEN
    SIGNAL SQLSTATE '45000'
      SET MESSAGE_TEXT = 'A personal expense can only be split to its payer';
  END IF;

  IF v_group IS NOT NULL AND NOT EXISTS (
       SELECT 1 FROM group_members
        WHERE group_id = v_group AND user_id = NEW.user_id AND status = 'active') THEN
    SIGNAL SQLSTATE '45000'
      SET MESSAGE_TEXT = 'Participant must be an active member of the group';
  END IF;

  IF NEW.share_amount > v_total THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Share cannot exceed the expense total';
  END IF;
END$$

-- AFTER INSERT: tell a participant they owe money (first version only) --
CREATE TRIGGER trg_expense_splits_after_insert
AFTER INSERT ON expense_splits
FOR EACH ROW
BEGIN
  DECLARE v_payer INT UNSIGNED;
  DECLARE v_version INT UNSIGNED;
  DECLARE v_desc VARCHAR(120);
  DECLARE v_payer_name VARCHAR(100);

  SELECT e.paid_by, e.version, e.description, u.full_name
    INTO v_payer, v_version, v_desc, v_payer_name
    FROM expenses e JOIN users u ON u.user_id = e.paid_by
   WHERE e.expense_id = NEW.expense_id;

  IF v_version = 1 AND NEW.user_id <> v_payer AND NEW.share_amount > 0
     AND NEW.user_id <> COALESCE(@app_user_id, 0) THEN
    INSERT INTO notifications (user_id, type, title, message, entity_type, entity_id)
    VALUES (NEW.user_id, 'expense_added', 'New expense',
            CONCAT(v_payer_name, ' added "', v_desc, '". Your share: ₹', NEW.share_amount),
            'expense', NEW.expense_id);
  END IF;
END$$

-- AFTER DELETE: archive a removed split (happens when an expense is re-split)
CREATE TRIGGER trg_expense_splits_after_delete
AFTER DELETE ON expense_splits
FOR EACH ROW
BEGIN
  INSERT INTO audit_logs (table_name, record_id, action, old_data, changed_by)
  VALUES ('expense_splits', OLD.split_id, 'DELETE',
          JSON_OBJECT('expense_id', OLD.expense_id, 'user_id', OLD.user_id,
                      'share_amount', OLD.share_amount,
                      'share_percentage', OLD.share_percentage,
                      'share_units', OLD.share_units,
                      'share_adjustment', OLD.share_adjustment),
          @app_user_id);
END$$

-- AFTER INSERT: notify the other party + audit --------------------------
CREATE TRIGGER trg_settlements_after_insert
AFTER INSERT ON settlements
FOR EACH ROW
BEGIN
  DECLARE v_payer_name, v_payee_name VARCHAR(100);
  SELECT full_name INTO v_payer_name FROM users WHERE user_id = NEW.payer_id;
  SELECT full_name INTO v_payee_name FROM users WHERE user_id = NEW.payee_id;

  IF NEW.status = 'pending' THEN
    INSERT INTO notifications (user_id, type, title, message, entity_type, entity_id)
    VALUES (NEW.payee_id, 'settlement_request', 'Please confirm a payment',
            CONCAT(v_payer_name, ' says they paid you ₹', NEW.amount, '. Confirm or reject.'),
            'settlement', NEW.settlement_id);
  ELSEIF NEW.status = 'confirmed' THEN
    INSERT INTO notifications (user_id, type, title, message, entity_type, entity_id)
    VALUES (NEW.payer_id, 'settlement_confirmed', 'Payment recorded',
            CONCAT(v_payee_name, ' recorded receiving ₹', NEW.amount, ' from you.'),
            'settlement', NEW.settlement_id);
  END IF;

  INSERT INTO audit_logs (table_name, record_id, action, new_data, changed_by)
  VALUES ('settlements', NEW.settlement_id, 'INSERT',
          JSON_OBJECT('group_id', NEW.group_id, 'payer_id', NEW.payer_id,
                      'payee_id', NEW.payee_id, 'amount', NEW.amount, 'status', NEW.status),
          @app_user_id);
END$$

-- BEFORE UPDATE: settlement state machine -------------------------------
--   pending -> confirmed | rejected | cancelled ; final states are immutable
CREATE TRIGGER trg_settlements_before_update
BEFORE UPDATE ON settlements
FOR EACH ROW
BEGIN
  IF OLD.status <> 'pending' THEN
    SIGNAL SQLSTATE '45000'
      SET MESSAGE_TEXT = 'Settlement is final (confirmed/rejected/cancelled) and cannot be changed';
  END IF;

  IF NEW.amount <> OLD.amount OR NEW.payer_id <> OLD.payer_id
     OR NEW.payee_id <> OLD.payee_id OR NEW.group_id <> OLD.group_id THEN
    SIGNAL SQLSTATE '45000'
      SET MESSAGE_TEXT = 'Settlement amount and parties cannot be edited; cancel and re-record';
  END IF;

  IF NEW.status <> OLD.status THEN
    SET NEW.responded_at = NOW();
  END IF;
END$$

-- AFTER UPDATE: tell the payer the outcome + audit ----------------------
CREATE TRIGGER trg_settlements_after_update
AFTER UPDATE ON settlements
FOR EACH ROW
BEGIN
  IF NEW.status IN ('confirmed','rejected') AND OLD.status = 'pending' THEN
    INSERT INTO notifications (user_id, type, title, message, entity_type, entity_id)
    VALUES (NEW.payer_id,
            IF(NEW.status = 'confirmed', 'settlement_confirmed', 'settlement_rejected'),
            IF(NEW.status = 'confirmed', 'Payment confirmed', 'Payment rejected'),
            CONCAT('Your payment of ₹', NEW.amount, ' was ', NEW.status, '.'),
            'settlement', NEW.settlement_id);
  END IF;

  INSERT INTO audit_logs (table_name, record_id, action, old_data, new_data, changed_by)
  VALUES ('settlements', NEW.settlement_id, 'UPDATE',
          JSON_OBJECT('status', OLD.status), JSON_OBJECT('status', NEW.status),
          @app_user_id);
END$$

-- BEFORE DELETE: confirmed money movements can never be deleted ---------
CREATE TRIGGER trg_settlements_before_delete
BEFORE DELETE ON settlements
FOR EACH ROW
BEGIN
  IF OLD.status = 'confirmed' THEN
    SIGNAL SQLSTATE '45000'
      SET MESSAGE_TEXT = 'Confirmed settlements cannot be deleted; record a reverse settlement instead';
  END IF;
END$$

DELIMITER ;

-- >>> procedures/procedures.sql
-- =====================================================================
-- SplitWise+ | procedures.sql — stored procedures
-- Multi-step writes run inside a transaction with an EXIT handler that
-- rolls back and re-raises the error (atomicity).
-- =====================================================================
SET NAMES utf8mb4;
USE splitwise_plus;

DROP PROCEDURE IF EXISTS sp_record_settlement;
DROP PROCEDURE IF EXISTS sp_respond_settlement;
DROP PROCEDURE IF EXISTS sp_add_equal_expense;
DROP PROCEDURE IF EXISTS sp_get_group_balances;
DROP PROCEDURE IF EXISTS sp_spending_summary;

DELIMITER $$

-- ---------------------------------------------------------------------
-- Record a settlement.
--  * Only payer or payee may record it.
--  * Recorded by payee -> confirmed; recorded by payer -> pending.
--  * Amount <= payer's outstanding payable and <= payee's outstanding
--    receivable, both reduced by pending settlements (stops duplicates).
--  * Locks the group's membership rows FOR UPDATE, so two concurrent
--    settlements in one group are checked one after the other.
--  * Same request_token twice -> returns the existing id (idempotent).
-- ---------------------------------------------------------------------
CREATE PROCEDURE sp_record_settlement(
  IN  p_group_id    INT UNSIGNED,
  IN  p_payer_id    INT UNSIGNED,
  IN  p_payee_id    INT UNSIGNED,
  IN  p_amount      DECIMAL(12,2),
  IN  p_date        DATE,
  IN  p_method      VARCHAR(20),
  IN  p_note        VARCHAR(255),
  IN  p_created_by  INT UNSIGNED,
  IN  p_token       CHAR(36),
  OUT p_settlement_id INT UNSIGNED)
BEGIN
  DECLARE v_locked INT;
  DECLARE v_payer_net, v_payee_net, v_pending_out, v_pending_in DECIMAL(12,2);
  DECLARE v_status VARCHAR(10);
  DECLARE v_msg VARCHAR(255);

  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    ROLLBACK;
    RESIGNAL;
  END;

  IF p_created_by NOT IN (p_payer_id, p_payee_id) THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Only the payer or the payee can record a settlement';
  END IF;
  IF p_amount IS NULL OR p_amount <= 0 THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Settlement amount must be positive';
  END IF;
  IF p_date > CURDATE() THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Settlement date cannot be in the future';
  END IF;

  START TRANSACTION;

  -- serialise settlements per group
  SELECT COUNT(*) INTO v_locked
    FROM group_members WHERE group_id = p_group_id FOR UPDATE;

  -- idempotent replay
  SET p_settlement_id = NULL;
  SELECT settlement_id INTO p_settlement_id
    FROM settlements WHERE request_token = p_token;

  IF p_settlement_id IS NULL THEN
    IF (SELECT COUNT(*) FROM group_members
         WHERE group_id = p_group_id AND user_id IN (p_payer_id, p_payee_id)) <> 2 THEN
      SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Payer and payee must both be members of the group';
    END IF;

    SET v_payer_net = fn_member_net_balance(p_group_id, p_payer_id);
    SET v_payee_net = fn_member_net_balance(p_group_id, p_payee_id);

    SELECT COALESCE(SUM(amount), 0) INTO v_pending_out
      FROM settlements WHERE group_id = p_group_id AND payer_id = p_payer_id AND status = 'pending';
    SELECT COALESCE(SUM(amount), 0) INTO v_pending_in
      FROM settlements WHERE group_id = p_group_id AND payee_id = p_payee_id AND status = 'pending';

    IF p_amount > (-v_payer_net - v_pending_out) THEN
      SET v_msg = CONCAT('Amount exceeds what the payer owes (available: ₹',
                         GREATEST(-v_payer_net - v_pending_out, 0), ')');
      SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = v_msg;
    END IF;
    IF p_amount > (v_payee_net - v_pending_in) THEN
      SET v_msg = CONCAT('Amount exceeds what the payee is owed (available: ₹',
                         GREATEST(v_payee_net - v_pending_in, 0), ')');
      SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = v_msg;
    END IF;

    SET v_status = IF(p_created_by = p_payee_id, 'confirmed', 'pending');

    INSERT INTO settlements (group_id, payer_id, payee_id, amount, settlement_date, method,
                             note, status, created_by, responded_at, request_token)
    VALUES (p_group_id, p_payer_id, p_payee_id, p_amount, p_date, p_method,
            p_note, v_status, p_created_by,
            IF(v_status = 'confirmed', NOW(), NULL), p_token);

    SET p_settlement_id = LAST_INSERT_ID();
  END IF;

  COMMIT;
END$$

-- ---------------------------------------------------------------------
-- Respond to a pending settlement: payee confirms/rejects, creator cancels.
-- The trigger trg_settlements_before_update enforces the state machine.
-- ---------------------------------------------------------------------
CREATE PROCEDURE sp_respond_settlement(
  IN p_settlement_id INT UNSIGNED,
  IN p_user_id       INT UNSIGNED,
  IN p_action        VARCHAR(10))      -- 'confirm' | 'reject' | 'cancel'
BEGIN
  DECLARE v_status VARCHAR(10);
  DECLARE v_payee, v_creator INT UNSIGNED;

  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    ROLLBACK;
    RESIGNAL;
  END;

  START TRANSACTION;

  SELECT status, payee_id, created_by INTO v_status, v_payee, v_creator
    FROM settlements WHERE settlement_id = p_settlement_id FOR UPDATE;

  IF v_status IS NULL THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Settlement not found';
  END IF;
  IF v_status <> 'pending' THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Only pending settlements can be answered';
  END IF;

  IF p_action IN ('confirm','reject') AND p_user_id <> v_payee THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Only the payee can confirm or reject';
  ELSEIF p_action = 'cancel' AND p_user_id <> v_creator THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Only the creator can cancel';
  ELSEIF p_action NOT IN ('confirm','reject','cancel') THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Unknown action';
  END IF;

  UPDATE settlements
     SET status = CASE p_action WHEN 'confirm' THEN 'confirmed'
                                WHEN 'reject'  THEN 'rejected'
                                ELSE 'cancelled' END
   WHERE settlement_id = p_settlement_id;

  COMMIT;
END$$

-- ---------------------------------------------------------------------
-- Add an equal-split expense entirely in SQL (used by seed data + demos).
-- p_participants: comma-separated user ids, e.g. '2,3,5'.
-- Rounding: every participant gets FLOOR(total/n) paise; the leftover
-- paise (< n) go one each to the payer first, then ascending user_id.
-- The application uses the same rule in PHP (SplitCalculator).
-- ---------------------------------------------------------------------
CREATE PROCEDURE sp_add_equal_expense(
  IN  p_group_id     INT UNSIGNED,
  IN  p_paid_by      INT UNSIGNED,
  IN  p_created_by   INT UNSIGNED,
  IN  p_category_id  SMALLINT UNSIGNED,
  IN  p_description  VARCHAR(120),
  IN  p_total        DECIMAL(12,2),
  IN  p_date         DATE,
  IN  p_participants VARCHAR(500),
  OUT p_expense_id   INT UNSIGNED)
BEGIN
  DECLARE v_n INT;
  DECLARE v_total_paise BIGINT;
  DECLARE v_base BIGINT;
  DECLARE v_left INT;

  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    ROLLBACK;
    RESIGNAL;
  END;

  IF p_participants IS NULL OR NOT REGEXP_LIKE(p_participants, '^[0-9]+(,[0-9]+)*$') THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Participants must be a comma-separated list of user ids';
  END IF;

  START TRANSACTION;

  INSERT INTO expenses (group_id, paid_by, created_by, category_id, description,
                        total_amount, split_method, expense_date)
  VALUES (p_group_id, p_paid_by, p_created_by, p_category_id, p_description,
          p_total, 'equal', p_date);
  SET p_expense_id = LAST_INSERT_ID();

  SELECT COUNT(DISTINCT jt.uid) INTO v_n
    FROM JSON_TABLE(CONCAT('[', p_participants, ']'), '$[*]'
                    COLUMNS (uid INT UNSIGNED PATH '$')) jt;

  SET v_total_paise = ROUND(p_total * 100);
  SET v_base = FLOOR(v_total_paise / v_n);
  SET v_left = v_total_paise - v_base * v_n;

  INSERT INTO expense_splits (expense_id, user_id, share_amount)
  SELECT p_expense_id,
         r.uid,
         (v_base + IF(r.rn <= v_left, 1, 0)) / 100
    FROM (SELECT d.uid,
                 ROW_NUMBER() OVER (ORDER BY (d.uid = p_paid_by) DESC, d.uid) AS rn
            FROM (SELECT DISTINCT jt.uid
                    FROM JSON_TABLE(CONCAT('[', p_participants, ']'), '$[*]'
                                    COLUMNS (uid INT UNSIGNED PATH '$')) jt) d) r;

  IF fn_expense_split_gap(p_expense_id) <> 0 THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Split total does not match expense total';
  END IF;

  COMMIT;
END$$

-- ---------------------------------------------------------------------
CREATE PROCEDURE sp_get_group_balances(IN p_group_id INT UNSIGNED)
READS SQL DATA
BEGIN
  SELECT user_id, full_name, member_status, total_paid, total_owed,
         settled_paid, settled_received, net_balance
    FROM v_group_member_balances
   WHERE group_id = p_group_id
   ORDER BY net_balance DESC, full_name;
END$$

-- Category-wise spending (user's share) between two dates --------------
CREATE PROCEDURE sp_spending_summary(
  IN p_user_id INT UNSIGNED, IN p_from DATE, IN p_to DATE)
READS SQL DATA
BEGIN
  SELECT COALESCE(pc.name, c.name)  AS category_group,
         c.name                     AS category,
         COUNT(*)                   AS expense_count,
         SUM(s.share_amount)        AS my_share
    FROM expense_splits s
    JOIN expenses e         ON e.expense_id = s.expense_id
    JOIN categories c       ON c.category_id = e.category_id
    LEFT JOIN categories pc ON pc.category_id = c.parent_category_id
   WHERE s.user_id = p_user_id
     AND e.is_deleted = 0
     AND e.expense_date BETWEEN p_from AND p_to
   GROUP BY COALESCE(pc.name, c.name), c.name
   ORDER BY my_share DESC;
END$$

DELIMITER ;

